 * Man hinh: chi in ket qua Controller dua vao qua thuoc tinh; display() khong tham so,
 * goi 1 lan cho 1 luong: in cau thong bao, HOAC in bang chi tieu + dong Total.
 *
 * @author CuongThai Academy
 */
public class ExpenseView {

    // Cac dong bang can in
    private List<ExpenseResponseDTO> responseList;

    // Tong tien da dinh dang
    private String total;

    // Cau thong bao can in (rong thi in bang)
    private String message;

    // Constructor: chua co gi de in
    public ExpenseView() {
        responseList = new ArrayList<>();
        total = "";
        message = "";
    }

    // Controller dua cac dong bang vao
    public void setResponseList(List<ExpenseResponseDTO> responseList) {
        this.responseList = responseList;
    }

    // Controller dua tong tien vao
    public void setTotal(String total) {
        this.total = total;
    }

    // Controller dua cau thong bao vao
    public void setMessage(String message) {
        this.message = message;
    }

    // In ket qua cua 1 luong roi xoa cau thong bao de luong sau bat dau sach
    public void display() {
        // Co cau thong bao thi chi in cau do
        if (!message.isEmpty()) {
            System.out.println(message);
        } else {
            // Bang theo de: tieu de cot, tung dong, dong Total
            System.out.println(String.format(Constants.HEADER_FORMAT, Message.HEADER_ID,
                    Message.HEADER_DATE, Message.HEADER_AMOUNT, Message.HEADER_CONTENT));

            // Moi chi tieu 1 dong
            for (ExpenseResponseDTO responseDTO : responseList) {
                System.out.println(responseDTO);
            }

            System.out.println(Message.TOTAL_LABEL.concat(total));
        }

        message = "";
    }
}

