package controller;

import constants.Message;
import dto.ExpenseRequestDTO;
import dto.ExpenseResponseDTO;
import java.util.List;
import repository.ExpenseRepository;
import service.ExpenseService;
import view.ExpenseView;

/**
 * Dieu phoi: nhan phieu DTO tu Main, goi Repository (CRUD), dua du lieu cho Service tinh
 * (ID tu tang, dong bang, tong tien), roi dua ket qua cho View in — 1 lan cho 1 luong.
 * Khong nhap, khong in, khong import model.
 *
 * @author CuongThai Academy
 */
public class ExpenseController {

    // Kho chi tieu (CRUD o Controller, khong o Service)
    private ExpenseRepository expenseRepository;

    // Nghiep vu tinh toan
    private ExpenseService expenseService;

    // Man hinh in ket qua
    private ExpenseView expenseView;

    // Constructor: tao repository, service va view
    public ExpenseController() {
        expenseRepository = new ExpenseRepository();
        expenseService = new ExpenseService();
        expenseView = new ExpenseView();
    }

    // Mo chuong trinh: kho nap cac dong Main da doc tu tep
    public void loadExpenses(ExpenseRequestDTO expenseRequestDTO) {
        expenseRepository.loadExpenses(expenseRequestDTO.getLineList());
    }

    // Chuc nang 1: Service tao chi tieu voi ID moi, kho them va ghi tep, View bao ID
    public void addExpense(ExpenseRequestDTO expenseRequestDTO) throws Exception {
        int expenseId = expenseService.generateNextId(expenseRepository.getExpenseList());

        expenseRepository.addExpense(expenseService.createExpense(expenseRequestDTO, expenseId));

        // Bao them thanh cong kem ID vua cap
        expenseView.setMessage(String.format(Message.ADD_SUCCESS, expenseId));
        expenseView.display();
    }

    // Chuc nang 2: kho lay danh sach, Service doi thanh dong bang + tong tien, View in (displayAll)
    public void displayAll() {
        List<ExpenseResponseDTO> responseList
                = expenseService.toResponseList(expenseRepository.getExpenseList());

        // Chua co chi tieu nao thi bao, co thi dua bang + tong tien cho View
        if (responseList.isEmpty()) {
            expenseView.setMessage(Message.NO_EXPENSE);
        } else {
            // Co chi tieu: dua cac dong va tong tien
            expenseView.setResponseList(responseList);
            expenseView.setTotal(expenseService.calculateTotal(expenseRepository.getExpenseList()));
        }

        expenseView.display();
    }

    // Chuc nang 3: kho xoa theo ID trong phieu, View bao thanh cong hoac that bai (cau cua de)
    public void deleteExpense(ExpenseRequestDTO expenseRequestDTO) throws Exception {
        // Kho tra false khi khong co ID do
        if (expenseRepository.deleteExpense(expenseRequestDTO.getId())) {
            expenseView.setMessage(Message.DELETE_SUCCESS);
        } else {
            // Khong co ID nay
            expenseView.setMessage(Message.DELETE_FAIL);
        }

        expenseView.display();
    }
}

