package repository;

import constants.Constants;
import constants.Message;
import java.util.ArrayList;
import java.util.List;
import model.Expense;
import utils.FileUtils;

/**
 * Kho du lieu: giu danh sach chi tieu, them/xoa/lay (CRUD), tach cac dong Main doc tu tep
 * thanh chi tieu, va ghi lai tep sau moi lan thay doi.
 *
 * @author CuongThai Academy
 */
public class ExpenseRepository {

    // Danh sach chi tieu trong bo nho
    private List<Expense> expenseList;

    // Constructor: tao danh sach rong
    public ExpenseRepository() {
        expenseList = new ArrayList<>();
    }

    // Nap cac dong Main da doc tu tep, moi dong id|date|amount|content (dong hong thi bo qua)
    public void loadExpenses(List<String> lineList) {
        String[] partArray = null;

        // Doi tung dong thanh 1 chi tieu
        for (String line : lineList) {
            partArray = line.split(Constants.FILE_SEPARATOR_REGEX, Constants.FILE_FIELDS);

            // Dong thieu cot thi bo qua
            if (partArray.length < Constants.FILE_FIELDS) {
                continue;
            }

            // Doi id va so tien sang so; dong hong thi bo qua, khong dung chuong trinh
            try {
                expenseList.add(new Expense(
                        Integer.parseInt(partArray[Constants.FIELD_ID].trim()),
                        partArray[Constants.FIELD_DATE].trim(),
                        Double.parseDouble(partArray[Constants.FIELD_AMOUNT].trim()),
                        partArray[Constants.FIELD_CONTENT]));
            } catch (NumberFormatException e) {
                // Bo qua dong hong
                continue;
            }
        }
    }

    // Tra ve ban sao danh sach de ben ngoai khong sua nham
    public List<Expense> getExpenseList() {
        return new ArrayList<>(expenseList);
    }

    // Them chi tieu (Service da cap ID) roi ghi lai tep (ham addExpense cua de)
    public void addExpense(Expense expense) throws Exception {
        expenseList.add(expense);
        saveToFile();
    }

    // Xoa chi tieu theo ID roi ghi lai tep; false = khong co ID do (ham deleteExpense cua de)
    public boolean deleteExpense(int expenseId) throws Exception {
        // Duyet tim chi tieu co ID can xoa
        for (Expense expense : expenseList) {
            // Trung ID thi xoa, ghi tep, bao thanh cong
            if (expense.getId() == expenseId) {
                expenseList.remove(expense);
                saveToFile();
                return true;
            }
        }

        return false;
    }

    // Ghi toan bo danh sach xuong tep, moi chi tieu 1 dong
    private void saveToFile() throws Exception {
        List<String> lineList = new ArrayList<>();

        // Ghep tung chi tieu thanh 1 dong id|date|amount|content
        for (Expense expense : expenseList) {
            lineList.add(String.join(Constants.FILE_SEPARATOR, String.valueOf(expense.getId()),
                    expense.getDate(), String.valueOf(expense.getAmount()), expense.getContent()));
        }

        // Ghi tep, loi thi bao cho nguoi dung
        try {
            FileUtils.writeLines(Constants.FILE_NAME, lineList);
        } catch (Exception e) {
            // Ghi tep that bai: bao loi ro rang
            throw new Exception(Message.WRITE_FAIL);
        }
    }
}

package service;

import constants.Constants;
import dto.ExpenseRequestDTO;
import dto.ExpenseResponseDTO;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import model.Expense;

/**
 * Nghiep vu: ID tu tang (lon nhat + 1), tao chi tieu, doi sang dong bang, tinh tong tien.
 * Chi tinh tren du lieu Controller dua vao — KHONG giu, KHONG goi Repository.
 *
 * @author CuongThai Academy
 */
public class ExpenseService {

    // Constructor: service khong giu du lieu nao
    public ExpenseService() {
    }

    // Tim ID lon nhat roi cong 1 (danh sach rong thi ID dau tien la 1)
    public int generateNextId(List<Expense> expenseList) {
        int maxId = Constants.START_ID;

        // Duyet tim ID lon nhat
        for (Expense expense : expenseList) {
            // Gap ID lon hon thi cap nhat
            if (expense.getId() > maxId) {
                maxId = expense.getId();
            }
        }

        return maxId + 1;
    }

    // Tao chi tieu moi tu phieu nhap voi ID Controller vua xin
    public Expense createExpense(ExpenseRequestDTO expenseRequestDTO, int expenseId) {
        return new Expense(expenseId, expenseRequestDTO.getDate(), expenseRequestDTO.getAmount(),
                expenseRequestDTO.getContent());
    }

    // Doi danh sach chi tieu sang cac dong bang de View in (tien da dinh dang)
    public List<ExpenseResponseDTO> toResponseList(List<Expense> expenseList) {
        List<ExpenseResponseDTO> responseList = new ArrayList<>();

        // Moi chi tieu 1 dong
        for (Expense expense : expenseList) {
            responseList.add(new ExpenseResponseDTO(expense.getId(), expense.getDate(),
                    formatMoney(expense.getAmount()), expense.getContent()));
        }

        return responseList;
    }

    // Tinh tong tien tat ca chi tieu (da dinh dang)
    public String calculateTotal(List<Expense> expenseList) {
        double total = 0;

        // Cong don so tien tung chi tieu
        for (Expense expense : expenseList) {
            total += expense.getAmount();
        }

        return formatMoney(total);
    }

    // Dinh dang tien: 100 / 100.5, luon dau cham (Locale.US) ke ca may tieng Viet
    private String formatMoney(double amount) {
        DecimalFormat moneyFormat = new DecimalFormat(Constants.MONEY_FORMAT,
                new DecimalFormatSymbols(Locale.US));

        return moneyFormat.format(amount);
    }
}

package utils;

import constants.Constants;
import java.io.BufferedReader;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;

/**
 * Doc va ghi tep text theo tung dong, luon bang ma UTF-8 (khong theo bang ma mac dinh cua may).
 *
 * @author CuongThai Academy
 */
public final class FileUtils {

    // Constructor private: lop chi co ham static (checklist 3.4)
    private FileUtils() {
    }

    // Doc tat ca dong cua tep; tep chua co (lan chay dau) thi tra ve danh sach rong
    public static List<String> readLines(String fileName) throws IOException {
        List<String> lineList = new ArrayList<>();
        File file = new File(fileName);
        String line = null;

        // Chua co tep thi khong co gi de doc
        if (!file.exists()) {
            return lineList;
        }

        // try-with-resources: tu dong dong tep ke ca khi loi
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
                new FileInputStream(file), Constants.FILE_CHARSET))) {
            line = reader.readLine();

            // Doc tung dong cho den het tep
            while (line != null) {
                lineList.add(line);
                line = reader.readLine();
            }
        }

        return lineList;
    }

    // Ghi de toan bo tep bang danh sach dong moi (tao thu muc data neu chua co)
    public static void writeLines(String fileName, List<String> lineList)
            throws IOException {
        File file = new File(fileName);
        File folder = file.getParentFile();

        // Lan chay dau chua co thu muc data thi tao
        if ((folder != null) && (!folder.exists())) {
            folder.mkdirs();
        }

        // try-with-resources: tu dong dong tep ke ca khi loi
        try (PrintWriter writer = new PrintWriter(new OutputStreamWriter(
                new FileOutputStream(file), Constants.FILE_CHARSET))) {
            // Ghi tung dong
            for (String line : lineList) {
                writer.println(line);
            }

            // PrintWriter khong nem loi nen phai tu hoi
            if (writer.checkError()) {
                throw new IOException(fileName);
            }
        }
    }
}

package utils;

import constants.Constants;
import constants.Message;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Locale;

/**
 * Kiem du lieu nhap: so nguyen, lua chon menu, ngay, so tien, noi dung.
 * Sai thi nem Exception kem cau bao loi noi ro sai gi va phai nhap the nao.
 *
 * @author CuongThai Academy
 */
public final class Validation {

    // Constructor private: lop chi co ham static (checklist 3.4)
    private Validation() {
    }

    // Kiem chuoi la so nguyen (dung cho ID can xoa)
    public static int getInt(String input) throws Exception {
        // Doi chuoi sang so nguyen (bo dau cach 2 dau truoc)
        try {
            return Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // Go chu hoac de trong thi bao phai nhap so
            throw new Exception(Message.INVALID_NUMBER);
        }
    }

    // Kiem lua chon menu nam trong [min, max]
    public static int getChoice(String input, int min, int max) throws Exception {
        int choice = getInt(input);

        // Ngoai khoang menu thi bao khoang dung
        if ((choice < min) || (choice > max)) {
            throw new Exception(String.format(Message.INVALID_RANGE, min, max));
        }

        return choice;
    }

    // Kiem ngay dung dang dd-MMM-yyyy va co that; tra ve dang chuan (11-apr-2009 -> 11-Apr-2009)
    public static String getDate(String input) throws Exception {
        String text = input.trim();
        SimpleDateFormat dateFormat = new SimpleDateFormat(Constants.DATE_FORMAT, Locale.ENGLISH);
        Date date = null;

        // Khong cho tu "lam tron" ngay sai (31-Feb thanh 03-Mar); ten thang luon tieng Anh
        dateFormat.setLenient(false);

        // Sai hinh dang (vd 2009-04-20, 11-Apr-09, 11-Apr-2009abc) thi bao loi
        if (!text.matches(Constants.DATE_REGEX)) {
            throw new Exception(Message.INVALID_DATE);
        }

        // Doi sang Date; ngay khong co that thi bao loi
        try {
            date = dateFormat.parse(text);
        } catch (ParseException e) {
            // Vi du 31-Feb-2009
            throw new Exception(Message.INVALID_DATE);
        }

        return dateFormat.format(date);
    }

    // Kiem so tien la so thuc lon hon 0
    public static double getAmount(String input) throws Exception {
        double amount = 0;

        // Doi chuoi sang so thuc
        try {
            amount = Double.parseDouble(input.trim());
        } catch (NumberFormatException e) {
            // Go chu hoac de trong thi bao loi
            throw new Exception(Message.INVALID_AMOUNT);
        }

        // Chan NaN, Infinity (Java coi la so)
        if ((Double.isNaN(amount)) || (Double.isInfinite(amount))) {
            throw new Exception(Message.INVALID_AMOUNT);
        }

        // So tien phai duong
        if (amount <= 0) {
            throw new Exception(Message.AMOUNT_POSITIVE);
        }

        return amount;
    }

    // Kiem noi dung khong rong (go toan dau cach cung tinh la rong)
    public static String getContent(String input) throws Exception {
        String text = input.trim();

        // Rong sau khi bo dau cach thi bao loi
        if (text.isEmpty()) {
            throw new Exception(Message.EMPTY_CONTENT);
        }

        return text;
    }
}

